import { useState, useEffect } from 'react';
import { useWorkspace } from '../../context/WorkspaceContext';
import { forEachSelectedObject } from '../../utils/canvasSelection';

const toHexColor = (color) => {
  if (!color || typeof color !== 'string') return '#000000';
  if (color.startsWith('#')) {
    if (color.length === 4) {
      return `#${color[1]}${color[1]}${color[2]}${color[2]}${color[3]}${color[3]}`;
    }
    return color.length === 7 ? color : '#000000';
  }
  const match = color.match(/\d+/g);
  if (match && match.length >= 3) {
    return `#${match.slice(0, 3).map((n) => Number(n).toString(16).padStart(2, '0')).join('')}`;
  }
  return '#000000';
};

const PropertyPanel = () => {
  const { selectedObject, canvas } = useWorkspace();
  const [fill, setFill] = useState('#818cf8');
  const [opacity, setOpacity] = useState(1);

  const swatches = [
    '#000000', '#1e293b', '#475569', '#94a3b8', '#cbd5e1', '#ffffff',
    '#e11d48', '#f97316', '#eab308', '#22c55e', '#06b6d4', '#4f46e5',
    '#ab47bc', '#ec407a', '#26a69a', '#78909c', '#d4af37', '#8d6e63'
  ];

  const isMultiSelection = selectedObject?.type === 'activeSelection';
  const selectionCount = isMultiSelection ? selectedObject.getObjects().length : selectedObject ? 1 : 0;

  useEffect(() => {
    if (!selectedObject) return;
    const syncFrom = (obj) => {
      setFill(toHexColor(obj.fill || '#000000'));
      setOpacity(obj.opacity !== undefined ? obj.opacity : 1);
    };
    if (isMultiSelection) {
      const first = selectedObject.getObjects()[0];
      if (first) syncFrom(first);
      return;
    }
    syncFrom(selectedObject);
    selectedObject.on('modified', () => syncFrom(selectedObject));
    return () => selectedObject.off('modified');
  }, [selectedObject, isMultiSelection]);

  const update = (key, value) => {
    if (!selectedObject || !canvas) return;
    forEachSelectedObject(canvas, selectedObject, (obj) => obj.set(key, value));
    canvas.renderAll();
  };

  const removeSelected = () => {
    if (!selectedObject || !canvas) return;
    forEachSelectedObject(canvas, selectedObject, (obj) => canvas.remove(obj));
    canvas.discardActiveObject();
    canvas.renderAll();
  };

  if (!selectedObject) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center h-full">
        <div className="w-12 h-12 bg-app-hover dark:bg-white/5 rounded-full flex items-center justify-center text-xl mb-3">🎨</div>
        <p className="text-[11px] font-bold uppercase tracking-wider text-app-muted">Выберите объект для окрашивания</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4 p-4 bg-app-bg border-b border-app-border max-h-[50vh] overflow-y-auto custom-scrollbar select-none animate-in fade-in duration-200">
      {isMultiSelection && (
        <p className="text-[10px] font-bold uppercase tracking-wider text-indigo-600 dark:text-indigo-400 text-center">
          Выбрано объектов: {selectionCount}
        </p>
      )}

      <div className="bg-app-elevated dark:bg-white/[0.02] border border-app-border p-4 rounded-2xl space-y-4">
        <span className="text-[9px] font-black text-app-muted uppercase tracking-widest block">Палитра спектра</span>
        
        <div 
          className="h-32 rounded-xl relative overflow-hidden border border-app-border-strong dark:border-white/10 shadow-inner"
          style={{
            background: 'linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, #4f46e5, #e11d48, #eab308, #22c55e, #06b6d4)'
          }}
        >
          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/40" />
          <div className="absolute bottom-3 left-3 flex items-center gap-2 bg-black/60 px-2 py-1 rounded-md border border-white/10 backdrop-blur-sm">
             <div className="w-3 h-3 rounded-sm border border-white/20" style={{ backgroundColor: fill }} />
             <span className="text-[10px] font-mono text-slate-200 uppercase">{fill}</span>
          </div>
        </div>

        <div className="flex items-center gap-3 bg-app-hover dark:bg-[#121214] p-2 border border-app-border-strong dark:border-white/10 rounded-xl">
          <input 
            type="color" 
            value={fill} 
            onChange={(e) => { setFill(e.target.value); update('fill', e.target.value); }} 
            className="w-10 h-8 rounded-lg cursor-pointer border-0 bg-transparent p-0" 
          />
          <div className="flex-1 text-center">
            <span className="text-xs font-mono font-bold text-app-text dark:text-slate-200 uppercase tracking-wider">{fill}</span>
          </div>
        </div>
      </div>

      <div className="bg-app-elevated dark:bg-white/[0.02] border border-app-border p-4 rounded-2xl">
        <span className="text-[9px] font-black text-app-muted uppercase tracking-widest mb-3 block">Образцы (Swatches)</span>
        <div className="grid grid-cols-6 gap-2">
          {swatches.map((color) => (
            <button
              key={color}
              onClick={() => { setFill(color); update('fill', color); }}
              className={`aspect-square rounded-lg border transition-all transform hover:scale-110 active:scale-95 ${
                fill.toLowerCase() === color.toLowerCase()
                  ? 'border-indigo-500 dark:border-white scale-105 shadow-md ring-2 ring-indigo-500/50'
                  : 'border-app-border-strong dark:border-white/10'
              }`}
              style={{ backgroundColor: color }}
              title={color}
            />
          ))}
        </div>
      </div>

      <div className="bg-app-elevated dark:bg-white/[0.02] border border-app-border p-4 rounded-2xl">
        <span className="text-[9px] font-black text-app-muted uppercase tracking-widest mb-3 block">Непрозрачность слоя</span>
        <div className="flex items-center gap-4">
          <input 
            type="range" 
            min="0" 
            max="100" 
            value={Math.round(opacity * 100)}
            onChange={(e) => {
              const val = parseInt(e.target.value) / 100;
              setOpacity(val);
              update('opacity', val);
            }}
            className="flex-1 accent-indigo-500 h-1.5 bg-app-hover dark:bg-white/10 rounded-lg appearance-none cursor-pointer"
          />
          <span className="text-xs font-mono font-bold text-indigo-600 dark:text-indigo-400 w-10 text-right">{Math.round(opacity * 100)}%</span>
        </div>
      </div>

      <button 
        onClick={removeSelected}
        className="w-full py-3.5 bg-rose-500/5 hover:bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 dark:border-rose-500/10 hover:border-rose-500/30 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mt-2"
      >
        {isMultiSelection ? 'Удалить выбранные' : 'Удалить элемент'}
      </button>
    </div>
  );
};

export default PropertyPanel;
